/// 简洁度指令：level 0 / 越界 → `None`。
pub fn verbosity_directive(level: i64) -> Option<&'static str> {
    if level <= 0 || level > 4 {
        return None;
    }
    Some(VERBOSITY_LEVELS[level as usize])
}

/// 用 sentinel 包裹的引导块：level 0 → `None`。
pub fn render_steering_block(level: i64, sentinel: &str) -> Option<String> {
    let directive = verbosity_directive(level)?;
    let open = sentinel.trim();
    if open.is_empty() {
        return Some(directive.to_string());
    }
    let name = open.trim_start_matches('<').trim_end_matches('>');
    Some(format!("{open}\n{directive}\n</{name}>"))
}

